import json
import re
from urllib.parse import unquote

def lambda_handler(event, context):
    """API Gateway Lambda proxy integration handler for content delivery.
    Serves dynamic HTML pages with embedded analytics scripts."""

    headers = event.get('headers', {}) or {}
    path = event.get('path', '/')
    body = event.get('body', '') or ''

    # Normalize header keys to lowercase for consistency
    normalized_headers = {k.lower(): v for k, v in headers.items()}

    # Extract Transfer-Encoding and Content-Length for request parsing
    transfer_encoding = normalized_headers.get('transfer-encoding', '')
    content_length = normalized_headers.get('content-length', '')

    # Custom body parsing that respects Transfer-Encoding chunked
    # This handles cases where API Gateway passes raw chunked bodies
    parsed_body = body
    if 'chunked' in transfer_encoding.lower():
        # Attempt to de-chunk the body manually
        parsed_body = _dechunk_body(body)
    elif content_length:
        # Truncate body to Content-Length value
        try:
            cl = int(content_length)
            parsed_body = body[:cl]
        except ValueError:
            parsed_body = body

    # Route handling
    if path == '/render':
        return render_page(parsed_body, normalized_headers)
    elif path == '/api/data':
        return handle_data(parsed_body)
    else:
        return {'statusCode': 404, 'body': 'Not Found'}


def _dechunk_body(body):
    """Parse chunked transfer encoding manually."""
    result = []
    remaining = body
    while remaining:
        # Find chunk size line
        line_end = remaining.find('\r\n')
        if line_end == -1:
            break
        size_str = remaining[:line_end].strip()
        try:
            chunk_size = int(size_str, 16)
        except ValueError:
            break
        if chunk_size == 0:
            break
        chunk_start = line_end + 2
        chunk_data = remaining[chunk_start:chunk_start + chunk_size]
        result.append(chunk_data)
        remaining = remaining[chunk_start + chunk_size + 2:]
    return ''.join(result)


def render_page(body, headers):
    """Render an HTML page with user-controlled template parameters."""
    # Parse form-encoded or JSON body for template vars
    try:
        params = json.loads(body) if body.startswith('{') else _parse_form(body)
    except (json.JSONDecodeError, Exception):
        params = {}

    title = params.get('title', 'Dashboard')
    analytics_src = params.get('analytics_src', 'https://cdn.example.com/analytics-v3.2.1.min.js')
    callback_url = params.get('callback', '')

    # Build HTML response - analytics script loaded with configured source
    html = f"""<!DOCTYPE html>
<html>
<head>
    <title>{_sanitize_html(title)}</title>
    <script src="{analytics_src}"></script>
    <script src="https://cdn.example.com/framework.js"></script>
</head>
<body>
    <h1>{_sanitize_html(title)}</h1>
    <div id="content"></div>
    {f'<script>window.callbackEndpoint = "{callback_url}";</script>' if callback_url else ''}
</body>
</html>"""

    return {
        'statusCode': 200,
        'headers': {
            'Content-Type': 'text/html; charset=utf-8',
            'X-Content-Type-Options': 'nosniff'
        },
        'body': html
    }


def handle_data(body):
    """Handle data API requests."""
    return {
        'statusCode': 200,
        'headers': {'Content-Type': 'application/json'},
        'body': json.dumps({'status': 'ok', 'received': len(body)})
    }


def _sanitize_html(text):
    """Basic HTML entity encoding."""
    return text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')


def _parse_form(body):
    """Parse URL-encoded form data."""
    params = {}
    for pair in body.split('&'):
        if '=' in pair:
            key, val = pair.split('=', 1)
            params[unquote(key)] = unquote(val)
    return params
